import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as r,af as s}from"./chunks/mermaid.DrCHRkU0.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"Agent Harness 剖析","description":"","frontmatter":{},"headers":[],"relativePath":"zh/tech/patterns/agent/harness.md","filePath":"zh/tech/patterns/agent/harness.md","lastUpdated":1780925161000}'),n={name:"zh/tech/patterns/agent/harness.md"};function o(l,t,i,h,d,p){return r(),e("div",null,[...t[0]||(t[0]=[s('<h1 id="agent-harness-剖析" tabindex="-1">Agent Harness 剖析 <a class="header-anchor" href="#agent-harness-剖析" aria-label="Permalink to &quot;Agent Harness 剖析&quot;">​</a></h1><blockquote><p>原文：<a href="https://blog.langchain.com/the-anatomy-of-an-agent-harness/" target="_blank" rel="noreferrer">The Anatomy of an Agent Harness</a> — Vivek Trivedy</p></blockquote><h2 id="核心公式" tabindex="-1">核心公式 <a class="header-anchor" href="#核心公式" aria-label="Permalink to &quot;核心公式&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent = Model + Harness</span></span></code></pre></div><p>如果不是在设计模型，那就在设计 Harness。</p><p><strong>Harness</strong> 是将模型转化为工作引擎的所有代码、配置和执行逻辑。模型提供智能，Harness 让智能变得有用。</p><h2 id="模型做不到的事" tabindex="-1">模型做不到的事 <a class="header-anchor" href="#模型做不到的事" aria-label="Permalink to &quot;模型做不到的事&quot;">​</a></h2><p>模型（大多数）只能输入文本/图像/音频/视频，输出文本。天生无法：</p><ul><li>在交互间维持持久状态</li><li>执行代码</li><li>访问实时知识</li><li>搭建环境来完成任务</li></ul><p>这些全部是 Harness 层解决的。</p><h2 id="核心组件" tabindex="-1">核心组件 <a class="header-anchor" href="#核心组件" aria-label="Permalink to &quot;核心组件&quot;">​</a></h2><h3 id="_1-文件系统-持久存储-上下文管理" tabindex="-1">1. 文件系统（持久存储 &amp; 上下文管理） <a class="header-anchor" href="#_1-文件系统-持久存储-上下文管理" aria-label="Permalink to &quot;1. 文件系统（持久存储 &amp; 上下文管理）&quot;">​</a></h3><p>模型只能操作上下文窗口内的知识。Harness 提供文件系统抽象，让 Agent：</p><ul><li>拥有工作空间，读取数据、代码、文档</li><li>将中间结果存储到磁盘而非全部塞进上下文</li><li>跨 session 保持状态</li><li>多 Agent / 人类通过共享文件协作</li></ul><p><strong>Git</strong> 为文件系统增加了版本控制，Agent 可追踪工作、回滚错误、分支实验。</p><h3 id="_2-bash-代码-通用工具" tabindex="-1">2. Bash + 代码（通用工具） <a class="header-anchor" href="#_2-bash-代码-通用工具" aria-label="Permalink to &quot;2. Bash + 代码（通用工具）&quot;">​</a></h3><p>Harness 提供 Bash 工具，让模型能自主编写和执行代码来解决问题，而不需要预定义的每一个工具。</p><p>ReAct Loop：<code>推理 → 行动 → 观察 → 重复</code></p><p>代码执行是实现自主问题求解的默认通用策略。</p><h3 id="_3-沙箱-验证工具" tabindex="-1">3. 沙箱 &amp; 验证工具 <a class="header-anchor" href="#_3-沙箱-验证工具" aria-label="Permalink to &quot;3. 沙箱 &amp; 验证工具&quot;">​</a></h3><p>模型无法自己配置执行环境。Harness 负责：</p><ul><li><strong>沙箱</strong>：隔离、安全的代码执行环境，按需创建/销毁</li><li><strong>预装工具</strong>：语言运行时、Git、测试框架、浏览器</li><li><strong>自验证循环</strong>：Agent 写代码 → 运行测试 → 检查日志 → 修复错误</li></ul><h3 id="_4-记忆-搜索-持续学习" tabindex="-1">4. 记忆 &amp; 搜索（持续学习） <a class="header-anchor" href="#_4-记忆-搜索-持续学习" aria-label="Permalink to &quot;4. 记忆 &amp; 搜索（持续学习）&quot;">​</a></h3><p>模型的知识截止于训练数据。Harness 通过文件系统实现<strong>持续学习</strong>：</p><ul><li><code>AGENTS.md</code> 等记忆文件在 Agent 启动时注入上下文</li><li>Web Search / MCP (如 Context7) 获取训练后产生的新知识</li></ul><h3 id="_5-对抗-context-rot" tabindex="-1">5. 对抗 Context Rot <a class="header-anchor" href="#_5-对抗-context-rot" aria-label="Permalink to &quot;5. 对抗 Context Rot&quot;">​</a></h3><p>Context Rot：上下文窗口填充后，模型推理和完成任务的能力下降。</p><p>Harness 的主要工作就是<strong>传递好的上下文工程</strong>。</p><table tabindex="0"><thead><tr><th>策略</th><th>说明</th></tr></thead><tbody><tr><td><strong>压缩 (Compaction)</strong></td><td>上下文快满时，智能卸载和摘要已有内容</td></tr><tr><td><strong>工具输出卸载</strong></td><td>大工具输出只保留首尾 token，完整内容存文件系统</td></tr><tr><td><strong>Skills</strong></td><td>渐进式加载工具，避免启动时上下文过载</td></tr></tbody></table><h3 id="_6-长期自主执行" tabindex="-1">6. 长期自主执行 <a class="header-anchor" href="#_6-长期自主执行" aria-label="Permalink to &quot;6. 长期自主执行&quot;">​</a></h3><p>复杂任务需要跨越多个上下文窗口的规划、观察和验证。</p><ul><li><strong>Ralph Loop</strong>：拦截模型的退出尝试，在干净上下文中重新注入原始 Prompt，强迫 Agent 继续工作</li><li><strong>规划</strong>：将目标分解为步骤，通过 Prompt 和文件系统中的计划文件引导</li><li><strong>自验证</strong>：Agent 完成后自行检查正确性，或通过测试套件创建反馈循环</li></ul><h2 id="模型训练-harness-设计的耦合" tabindex="-1">模型训练 &amp; Harness 设计的耦合 <a class="header-anchor" href="#模型训练-harness-设计的耦合" aria-label="Permalink to &quot;模型训练 &amp; Harness 设计的耦合&quot;">​</a></h2><p>Claude Code、Codex 等产品采用 <strong>post-training</strong>：模型和 Harness 在循环中共同训练。</p><p>这创造了反馈循环：发现有用原语 → 加入 Harness → 用于训练下一代模型。</p><p><strong>有趣的副作用</strong>：改变工具逻辑会导致模型性能下降——这是 Harness 层面的过拟合。</p><blockquote><p>但这不意味着模型预训练用的 Harness 就是最优的。Terminal Bench 2.0 上，Opus 4.6 在 Claude Code 中得分远低于在其他 Harness 中——纯粹改变 Harness 就能让一个 Agent 从 Top 30 提升到 Top 5。</p></blockquote><h2 id="harness-的未来" tabindex="-1">Harness 的未来 <a class="header-anchor" href="#harness-的未来" aria-label="Permalink to &quot;Harness 的未来&quot;">​</a></h2><p>随着模型能力增强，部分 Harness 功能会被吸收进模型本身。但：</p><blockquote><p>正如 Prompt Engineering 今天仍然有价值，Harness Engineering 仍将是构建好 Agent 的关键。</p></blockquote><p>Harness 不只是补丁模型缺陷的工具，更是<strong>围绕模型智能构建系统</strong>的工程化手段。</p><h2 id="对前端-ai-学习的启发" tabindex="-1">对前端 AI 学习的启发 <a class="header-anchor" href="#对前端-ai-学习的启发" aria-label="Permalink to &quot;对前端 AI 学习的启发&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Harness 组件</th><th>前端场景</th></tr></thead><tbody><tr><td>文件系统</td><td>工作区管理、跨项目上下文</td></tr><tr><td>沙箱</td><td>本地开发环境、Docker 隔离</td></tr><tr><td>自验证</td><td>自动化测试、Playwright E2E</td></tr><tr><td>Context 管理</td><td>Cursor Rules、上下文注入策略</td></tr><tr><td>Skills</td><td>VitePress 插件、浏览器扩展</td></tr></tbody></table><h2 id="相关文章" tabindex="-1">相关文章 <a class="header-anchor" href="#相关文章" aria-label="Permalink to &quot;相关文章&quot;">​</a></h2><ul><li><a href="./agent-design-patterns.html">Agent 设计模式</a></li><li><a href="./../protocols/mcp.html">MCP 协议</a></li><li><a href="./skills.html">Skills 机制</a></li><li><a href="./hooks.html">Hooks 模式</a></li></ul>',45)])])}const k=a(n,[["render",o]]);export{m as __pageData,k as default};
